head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setDataDragSelect]<br/>GridView 컴포넌트의 dataDragSelect 속성을 설정합니다.",
    "validation" : [
        "useShiftKey=true 이고, dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 인 경우에 dataDragSelect 속성이 적용됩니다.",
        "dragSelect(필수) 파라미터를 true 로 설정 시 마우스 Drag 로 다중 Cell 선택(직사각형)을 허용합니다.",
        "dragSelect(필수) 파라미터를 false 로 설정 시 마우스 Drag 로 다중 Cell 선택(직사각형)을 허용하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - target1 은 useShiftKey=true 고정(전제) + dataDragDrop/Self/Other/Cell 미부여(기본 false) 로 생성.
    //  - dataDragSelect 는 초기 미설정(기본 false). [setDataDragSelect] 버튼으로 par_dragSelect 값(true/false)을 적용.
    //  - true 적용 시 Body Cell 을 마우스로 Drag 하면 직사각형 다중 Cell 선택이 가능. 설정 결과는 getDataDragSelect() 반환값으로 확인.
    $c.gcm.createLabel('label="useShiftKey=true 고정(전제). [setDataDragSelect] 로 par_dragSelect 값 적용(getDataDragSelect 로 확인). true 면 Body Cell 을 Drag 하여 직사각형 다중 선택 → [선택 셀 출력] 로 확인."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === DataList(dlt_src) : 4 Column ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    // 데이터 4행 로드
    let srcData = [
        { "col1": "행1", "col2": "100", "col3": "Aa", "col4": "10" },
        { "col1": "행2", "col2": "200", "col3": "Bb", "col4": "20" },
        { "col1": "행3", "col2": "300", "col3": "Cc", "col4": "30" },
        { "col1": "행4", "col2": "400", "col3": "Dd", "col4": "40" }
    ];
    dlt_src.setJSON(srcData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === target1 : useShiftKey=true 고정 / dataDragSelect 미설정(기본 false) ===
    //  - dataDragDrop 계열은 전부 미부여(기본 false) → dataDragSelect 동작 전제 충족
    let srcCList = $c.gcm.createCList({ dataList: "data:dlt_src", useShiftKey: true });

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:300px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (setDataDragSelect 테스트 / useShiftKey=true)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);
};



// [setDataDragSelect] : par_dragSelect 값(true/false)을 Boolean 으로 target1 에 적용
//  - 설정 직후 쌍 get 메소드 getDataDragSelect() 호출로 반영 여부 확인 (§5 set 검증 규칙)
//  - true 설정 시 useShiftKey=true 전제 하에 Body Cell 을 마우스로 Drag 하면 직사각형 다중 Cell 선택 가능 (사용자 수동 Drag)
scwin.btn_setDataDragSelect_onclick = function () {
    let dragSelect = par_dragSelect.getText() === "true";

    target1.setDataDragSelect(dragSelect);

    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("setDataDragSelect(" + dragSelect + ") 호출");
    b.setReturnValue("getDataDragSelect() 반환값 : " + target1.getDataDragSelect());
};



// [선택 셀 출력] : Drag 로 선택된(직사각형) Cell 들의 row/col 과 값을 출력
//  - dataDragSelect 의 다중 Cell 선택은 포커스(focusedCell)로 표현됨 → getAllFocusedIndex 로 조회(focusMode 기본 cell)
//  - true 설정 + useShiftKey=true 전제에서 Body Cell 을 Drag 하여 직사각형 선택 후 출력
scwin.btn_printSelected_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let cells = target1.getAllFocusedIndex();
    if (!cells || cells.length === 0) {
        b.setReturnValue("선택된 Cell 없음 (true 설정 후 Body Cell 을 Drag 하여 선택하세요)");
        return;
    }
    b.setReturnValue("선택 Cell 수 : " + cells.length);
    for (let i = 0; i < cells.length; i++) {
        let colId = target1.getColumnID(cells[i].col);
        b.setReturnValue("  row=" + cells[i].row + ", col=" + colId + ", 값=" + dlt_src.getCellData(cells[i].row, colId));
    }
};
